CREATE TABLE IF NOT EXISTS "hr_attendance" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "attendance_date" date,
    "check_in_time" timestamp,
    "check_out_time" timestamp,
    "status" int,
    "overtime_hours" decimal(20,2),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_contract" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "contract_no" varchar(255),
    "contract_type" int,
    "start_date" date,
    "end_date" date,
    "sign_date" date,
    "probation_end_date" date,
    "position_id" bigint,
    "department_id" bigint,
    "salary" decimal(20,2),
    "status" int,
    "file_url" varchar(255),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_department" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "parent_id" bigint,
    "code" varchar(255),
    "name" varchar(255),
    "leader_id" bigint,
    "status" int,
    "remark" varchar(255),
    "sort" int,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_employee" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "emp_no" varchar(255),
    "name" varchar(255),
    "gender" int,
    "birth_date" date,
    "id_card" varchar(255),
    "phone" varchar(255),
    "email" varchar(255),
    "dept_id" bigint,
    "position_id" bigint,
    "hire_date" date,
    "leave_date" date,
    "status" int,
    "employment_type" int,
    "remark" varchar(255),
    "sort" int,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_interview" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "resume_id" bigint,
    "interview_round" int,
    "interviewer_id" bigint,
    "interview_time" timestamp,
    "interview_type" int,
    "result" int,
    "comment" varchar(255),
    "status" int,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_job_posting" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "position_id" bigint,
    "title" varchar(255),
    "headcount" int,
    "salary_range" varchar(255),
    "description" varchar(255),
    "requirement" varchar(255),
    "status" int,
    "publish_date" date,
    "close_date" date,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_leave_balance" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "leave_type_id" bigint,
    "year" int,
    "total_days" decimal(20,2),
    "used_days" decimal(20,2),
    "remaining_days" decimal(20,2),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_leave_request" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "leave_type_id" bigint,
    "start_date" date,
    "end_date" date,
    "days" decimal(20,2),
    "reason" varchar(255),
    "status" int,
    "approver_id" bigint,
    "approve_time" timestamp,
    "approve_remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_leave_type" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255),
    "code" varchar(255),
