);

CREATE TABLE IF NOT EXISTS "hr_position" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(255),
    "name" varchar(255),
    "dept_id" bigint,
    "level" int,
    "base_salary" decimal(20,2),
    "remark" varchar(255),
    "sort" int,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_resume" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "job_posting_id" bigint,
    "candidate_name" varchar(255),
    "phone" varchar(255),
    "email" varchar(255),
    "education" varchar(255),
    "experience_years" int,
    "resume_url" varchar(255),
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_salary" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "salary_month" varchar(255),
    "base_salary" decimal(20,2),
    "overtime_pay" decimal(20,2),
    "bonus" decimal(20,2),
    "deduction" decimal(20,2),
    "social_insurance" decimal(20,2),
    "housing_fund" decimal(20,2),
    "tax" decimal(20,2),
    "net_salary" decimal(20,2),
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hr_social_insurance_base" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" bigint,
    "year" int,
    "pension_base" decimal(20,2),
    "medical_base" decimal(20,2),
    "unemployment_base" decimal(20,2),
    "work_injury_base" decimal(20,2),
    "maternity_base" decimal(20,2),
    "housing_fund_base" decimal(20,2),
    "personal_pension_rate" decimal(20,2),
    "company_pension_rate" decimal(20,2),
    "personal_medical_rate" decimal(20,2),
    "company_medical_rate" decimal(20,2),
    "personal_unemployment_rate" decimal(20,2),
    "company_unemployment_rate" decimal(20,2),
    "company_work_injury_rate" decimal(20,2),
    "company_maternity_rate" decimal(20,2),
    "personal_housing_fund_rate" decimal(20,2),
    "company_housing_fund_rate" decimal(20,2),
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
